"""Run focused growth contracts in isolated Surefire copies after the root build."""
from __future__ import annotations

import argparse
import datetime
import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import time
import xml.etree.ElementTree as ET

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
MODULE = ROOT / "core/sail/lmdb"
JAVA_HOME = Path("/workspace/scratch/d0a0e51b9386/toolchain/jdk-25.0.5+8")
MAVEN = Path("/workspace/scratch/d0a0e51b9386/toolchain/maven-mvnd-1.0.6-linux-amd64/mvn/bin/mvn")


def digest(path):
    with Path(path).open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def tree(path):
    return {p.relative_to(path).as_posix(): digest(p) for p in sorted(path.rglob("*")) if p.is_file()}


def write(path, value):
    path.write_text(json.dumps(value, indent=2, sort_keys=True) + "\n")


def run(out, name, command):
    environment = os.environ.copy()
    environment["JAVA_HOME"] = str(JAVA_HOME)
    environment["PATH"] = str(JAVA_HOME / "bin") + os.pathsep + environment.get("PATH", "")
    record = {"argv": list(map(str, command)), "cwd": str(ROOT), "startedNs": time.time_ns(),
              "started": datetime.datetime.now(datetime.timezone.utc).isoformat()}
    write(out / (name + "-command.json"), record)
    with (out / (name + ".log")).open("wb") as log:
        result = subprocess.run(record["argv"], cwd=ROOT, env=environment, stdout=log, stderr=subprocess.STDOUT)
    record.update(exitCode=result.returncode, finishedNs=time.time_ns())
    write(out / (name + "-command.json"), record)
    print(name, "exit", result.returncode, flush=True)
    return record


def pom(out, classes, tests):
    namespace = "http://maven.apache.org/POM/4.0.0"
    ET.register_namespace("", namespace)
    document = ET.parse(MODULE / "pom.xml")
    root = document.getroot()
    tag = lambda name: "{" + namespace + "}" + name
    parent = root.find(tag("parent"))
    relative = parent.find(tag("relativePath"))
    if relative is None:
        relative = ET.SubElement(parent, tag("relativePath"))
    relative.text = str(ROOT / "core/sail/pom.xml")
    build = root.find(tag("build"))
    for name, value in (("directory", out / "target"), ("outputDirectory", classes),
                        ("testOutputDirectory", tests), ("testSourceDirectory", HERE / "src")):
        node = build.find(tag(name))
        if node is None:
            node = ET.SubElement(build, tag(name))
        node.text = str(value)
    destination = out / "pom.xml"
    document.write(destination, encoding="utf-8", xml_declaration=True)
    return destination


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("attempt")
    parser.add_argument("--classpath", required=True, type=Path)
    parser.add_argument("--overlay", action="append", type=Path, default=[])
    parser.add_argument("--source", action="append", type=Path, default=[])
    parser.add_argument("--selection", required=True)
    parser.add_argument("--property", action="append", default=[])
    parser.add_argument("--expected-failure", action="append", default=[])
    parser.add_argument("--slot-granted", action="store_true")
    args = parser.parse_args()
    if not args.slot_granted or Path(args.attempt).name != args.attempt:
        raise ValueError("A simple fresh attempt name and exclusive Java slot are required")
    out = HERE / "validation" / args.attempt
    out.mkdir(parents=True, exist_ok=False)
    shutil.copyfile(__file__, out / "runner-at-launch.py")
    cp_file = args.classpath.resolve(strict=True)
    cp = cp_file.read_text().strip()
    classes, tests = out / "classes", out / "test-classes"
    shutil.copytree(MODULE / "target/classes", classes)
    shutil.copytree(MODULE / "target/test-classes", tests)
    before = tree(MODULE / "src")
    input_record = {"classpathFile": str(cp_file), "classpathSha256": digest(cp_file),
                    "selection": args.selection, "properties": args.property, "sources": {}, "overlays": {}}
    for overlay in args.overlay:
        overlay = overlay.resolve(strict=True)
        input_record["overlays"][str(overlay)] = tree(overlay)
        shutil.copytree(overlay, classes, dirs_exist_ok=True)
    sources = []
    for source in args.source:
        source = source.resolve(strict=True)
        input_record["sources"][str(source)] = digest(source)
        destination = out / "sources" / source.name
        destination.parent.mkdir(exist_ok=True)
        if destination.exists():
            raise ValueError("Repeated source filename")
        shutil.copyfile(source, destination)
        sources.append(destination)
    write(out / "inputs.json", input_record)
    if sources:
        compiled = run(out, "compile", [JAVA_HOME / "bin/javac", "--release", "25", "-g", "-proc:none",
            "-implicit:none", "-sourcepath", "", "-cp", os.pathsep.join([str(classes), str(tests), cp]),
            "-d", tests, *sources])
        if compiled["exitCode"]:
            print((out / "compile.log").read_text())
            raise RuntimeError("Compilation failure is not qualifying red evidence")
    write(out / "production-class-files.json", tree(classes))
    write(out / "test-class-files.json", tree(tests))
    (out / "target/tmp/fork-1").mkdir(parents=True)
    command = [MAVEN, "-B", "-ntp", "-o", "-Dmaven.repo.local=.m2_repo", "-Pquick", "-DskipTests=false",
               "-f", pom(out, classes, tests), "-Dtest=" + args.selection, "-DforkCount=1",
               "-Drdf4j.lmdb.test.maxHeap=1G", "-Dsurefire.runOrder=alphabetical",
               *["-D" + item for item in args.property], "surefire:test"]
    executed = run(out, "tests", command)
    reports = out / "target/surefire-reports"
    shutil.copytree(reports, out / "surefire-reports")
    totals = {name: 0 for name in ("tests", "failures", "errors", "skipped")}
    cases, execution_classpaths = [], set()
    for report in sorted(reports.glob("TEST-*.xml")):
        suite = ET.parse(report).getroot()
        for name in totals:
            totals[name] += int(suite.attrib[name])
        properties = {p.attrib["name"]: p.attrib.get("value", "") for p in suite.findall("./properties/property")}
        execution_classpaths.add(properties["surefire.test.class.path"])
        for case in suite.findall("testcase"):
            failure = case.find("failure")
            error = case.find("error")
            cases.append({"class": case.attrib["classname"], "method": case.attrib["name"],
                          "failure": None if failure is None else failure.attrib.get("message", ""),
                          "error": None if error is None else error.attrib.get("message", "")})
    failed = {c["method"] for c in cases if c["failure"] is not None}
    expected = set(args.expected_failure)
    passed = (totals["tests"] > 0 and totals["errors"] == totals["skipped"] == 0 and failed == expected
              and totals["failures"] == len(expected) and (executed["exitCode"] != 0) == bool(expected)
              and len(execution_classpaths) == 1 and before == tree(MODULE / "src"))
    for actual_cp in execution_classpaths:
        entries = actual_cp.split(os.pathsep)
        passed &= entries[:2] == [str(tests), str(classes)]
        write(out / "execution-classpath.json", [{"path": entry,
            "identity": tree(Path(entry)) if Path(entry).is_dir() else digest(entry)} for entry in entries])
    receipt = {"passed": bool(passed), "results": totals, "expectedFailures": sorted(expected),
               "cases": cases, "testProcessExit": executed["exitCode"], "moduleSourcesUnchanged": before == tree(MODULE / "src")}
    write(out / "receipt.json", receipt)
    snippets = [line for report in sorted(reports.glob("*.txt")) for line in report.read_text().splitlines()
                if line.startswith(("Tests run:", "Test set:"))]
    evidence = "\nGrowth contracts " + args.attempt + "\nCommand: " + " ".join(map(str, command))
    evidence += "\nReport: " + str(reports) + "\n" + "\n".join(snippets) + "\n"
    (out / "evidence.txt").write_text(evidence)
    with (ROOT / "initial-evidence.txt").open("a") as initial:
        initial.write(evidence)
    print(evidence)
    print(json.dumps(receipt, indent=2))
    if not passed:
        sys.exit(1)


if __name__ == "__main__":
    main()
